<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Sign in — DeploySift</title><link rel="icon" type="image/svg+xml" href="/favicon.svg"><style>body{margin:0;background:#0B1220;color:#eaf4ff;font:15px system-ui;display:flex;min-height:100vh;align-items:center;justify-content:center}.card{background:#151F30;border:1px solid #1e3450;border-radius:14px;padding:34px;width:100%;max-width:400px}.brand{font-weight:900;letter-spacing:2px;font-size:20px}.brand span{color:#22D3EE}.sub{color:#8aa0bb}label{display:block;margin:14px 0 5px;color:#9fc2e3}input{width:100%;padding:10px;background:#0B1220;color:#fff;border:1px solid #29445f;border-radius:7px;box-sizing:border-box}button{width:100%;padding:11px;margin-top:20px;border:0;border-radius:7px;background:#22D3EE;color:#0B1220;font-weight:700;cursor:pointer;font-size:15px}button.ghost{background:transparent;border:1px solid #29445f;color:#9fc2e3;margin-top:10px}a{color:#818CF8;text-decoration:none}.err{color:#F87171;margin-top:12px;min-height:20px}.row{display:flex;gap:10px}.row button{flex:1}</style></head><body><div class="card"><div class="brand">DEPLOY<span>SIFT</span></div><p class="sub">Every clue. One diagnosis.</p><h1>Sign in</h1><form id="f"><label for="email">Email</label><input id="email" type="email" required autocomplete="email"><label for="password">Password</label><input id="password" type="password" required autocomplete="current-password"><div class="err" id="err"></div><button type="submit">Sign in</button></form><div class="row">@if(config('services.google.client_id'))<button class="ghost" onclick="location.href='/auth/google/redirect'">Google</button>@endif @if(config('services.github.client_id'))<button class="ghost" onclick="location.href='/auth/github/redirect'">GitHub</button>@endif</div><p class="sub">No account? <a href="/register">Register</a> · <a href="/">Back to app</a></p></div><script>const csrf=document.querySelector('meta[name=csrf-token]').content;fetch('/api/me',{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(r=>{if(r.ok)location.href='/';});document.querySelector('#f').addEventListener('submit',async v=>{v.preventDefault();let err=document.querySelector('#err');err.textContent='';let r=await fetch('/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({email:document.querySelector('#email').value,password:document.querySelector('#password').value})});if(r.ok)location.href='/';else{try{let j=await r.json();err.textContent=j.message||'Sign-in failed.';}catch(e){err.textContent='Sign-in failed.';}}});</script></body></html>
